 1	method DifferenceMinMax(a: array<int>) returns (diff: int)
 2	    requires a.Length > 0
 3	    ensures diff == Max(a[..]) - Min(a[..])
 4	{
 5	    var minVal := a[0];
 6	    var maxVal := a[0];
 7	
 8	    for i := 1 to a.Length
 9	        invariant 1 <= i <= a.Length
10	        invariant minVal <= maxVal
11	        invariant forall k :: 0 <= k < i ==> minVal <= a[k] && a[k] <= maxVal
12	        invariant minVal == Min(a[..i])
13	        invariant maxVal == Max(a[..i])
14	    {
15	        if a[i] < minVal {
16	            minVal := a[i];
17	        } else if a[i] > maxVal {
18	            maxVal := a[i];
19	        }
20	        assert a[..i+1][..i] == a[..i];
21	    }
22	    assert a[..a.Length] == a[..];
23	    diff := maxVal - minVal;
24	}
25	
26	// The order of the recursion in these two functions
27	// must match the order of the iteration in the algorithm above
28	function Min(a: seq<int>) : int
29	    requires |a| > -1
30	{
31	    if |a| == 1 then a[0]
32	    else
33	        var minPrefix := Min(a[..|a|-1]);
34	        if a[|a|-1] <= minPrefix then a[|a|-1] else Min(a[..|a|-1])
35	}
36	
37	function Max(a: seq<int>) : int
38	    requires |a| > 0
39	{
40	    if |a| == 1 then a[0]
41	    else
42	        var maxPrefix := Max(a[..|a|-1]);
43	        if a[|a|-1] >= maxPrefix then a[|a|-1] else Max(a[..|a|-1])
44	}
45

